import{_ as e,o,c as a,a2 as d}from"./chunks/framework.CmvPqeTF.js";const g=JSON.parse('{"title":"~/.ssh/config 导入导出","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ssh-config.md","filePath":"guide/ssh-config.md","lastUpdated":1788361893000}'),s={name:"guide/ssh-config.md"};function n(c,t,r,i,l,h){return o(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="ssh-config-导入导出" tabindex="-1">~/.ssh/config 导入导出 <a class="header-anchor" href="#ssh-config-导入导出" aria-label="Permalink to &quot;~/.ssh/config 导入导出&quot;">​</a></h1><p>侧栏「SSH 配置」面板（ActivityBar 第三个图标）直接管理 <code>~/.ssh/config</code>：结构化编辑主机条目，或把主机一键导入为 vShell 连接。</p><hr><h2 id="_1-面板结构" tabindex="-1">1. 面板结构 <a class="header-anchor" href="#_1-面板结构" aria-label="Permalink to &quot;1. 面板结构&quot;">​</a></h2><p>工具栏四个按钮：<strong>刷新</strong>、<strong>编辑源文件</strong>、<strong>添加主机</strong>、<strong>导入为连接</strong>。</p><p>主机条目以折叠卡片列表展示：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────┐</span></span>
<span class="line"><span>│ [Host] web-prod   user@1.2.3.4:22 │  折叠态：徽章 + 别名 + 元信息</span></span>
<span class="line"><span>│   （hover：✏️ 编辑  🗑 删除）        │</span></span>
<span class="line"><span>└──────────────────────────────────┘</span></span></code></pre></div><p>展开后是结构化编辑表单。</p><h2 id="_2-结构化编辑" tabindex="-1">2. 结构化编辑 <a class="header-anchor" href="#_2-结构化编辑" aria-label="Permalink to &quot;2. 结构化编辑&quot;">​</a></h2><p>每个条目对应 config 中一个 <code>Host</code>（或 <code>Match</code>）块：</p><table tabindex="0"><thead><tr><th>字段</th><th>对应指令</th></tr></thead><tbody><tr><td>主机别名</td><td><code>Host</code></td></tr><tr><td>主机名</td><td><code>HostName</code></td></tr><tr><td>用户名</td><td><code>User</code></td></tr><tr><td>端口</td><td><code>Port</code></td></tr><tr><td>密钥文件</td><td><code>IdentityFile</code></td></tr><tr><td>额外配置项</td><td>任意键值对，可增删（如 <code>ServerAliveInterval 60</code>）</td></tr></tbody></table><p>保存时以结构化形式<strong>整文件重写</strong>（缩进指令、块间空行、0600 权限）。删除主机需确认。</p><blockquote><p>解析器为扁平键值模型：支持 <code>Host</code> / <code>Match</code> 块内的大小写不敏感指令；不支持 <code>=</code> 分隔符、<code>Include</code> 展开与 <code>Match</code> 条件求值。复杂配置建议用「编辑源文件」。</p></blockquote><h2 id="_3-编辑源文件" tabindex="-1">3. 编辑源文件 <a class="header-anchor" href="#_3-编辑源文件" aria-label="Permalink to &quot;3. 编辑源文件&quot;">​</a></h2><p>以编辑器标签打开 <code>~/.ssh/config</code> 原文（标题即文件路径），用 Monaco 直接编辑，<code>⌘S</code> 保存整文件覆写。适合手工微调注释、复杂指令等结构化表单覆盖不到的内容（详见<a href="./editor.html">远程文件编辑</a>）。</p><h2 id="_4-导入为连接" tabindex="-1">4. 导入为连接 <a class="header-anchor" href="#_4-导入为连接" aria-label="Permalink to &quot;4. 导入为连接&quot;">​</a></h2><p>点击「导入为连接」后：</p><ol><li>列出全部候选主机：别名、<code>host:port</code>、用户、密钥文件，并用 <strong>绿√ / 红✕</strong> 标记 IdentityFile 是否存在</li><li>勾选需要的主机（支持全选 / 取消全选）</li><li>两种导入方式：</li></ol><table tabindex="0"><thead><tr><th>方式</th><th>行为</th></tr></thead><tbody><tr><td><strong>添加连接</strong></td><td>取第一个选中项读取详情（含私钥内容）<strong>预填连接表单</strong>，确认后才创建；有私钥时认证方式自动置为「私钥」</td></tr><tr><td><strong>直接导入 (N)</strong></td><td>批量创建连接，成功提示「已导入 N 个连接」</td></tr></tbody></table><p>导入规则：</p><ul><li>连接名 = Host 别名；<code>HostName</code> / <code>Port</code>（默认 22）/ <code>User</code> 缺省时按默认值兜底</li><li><code>IdentityFile</code> 可读时：认证方式为私钥，私钥<strong>内容</strong>加密入库；文件位于 <code>~/.ssh</code> 内时同时记录密钥名，之后在<a href="./connections.html">连接表单</a>中会显示为「从密钥管理选择」</li><li>无 IdentityFile 时：认证方式为密码（留空，连接前补填）</li></ul><h2 id="_5-与其他功能的关系" tabindex="-1">5. 与其他功能的关系 <a class="header-anchor" href="#_5-与其他功能的关系" aria-label="Permalink to &quot;5. 与其他功能的关系&quot;">​</a></h2><ul><li>导入的连接和其他连接一样进入<a href="./connections.html">连接管理</a>树</li><li><code>IdentityFile</code> 指向的密钥出现在<a href="./keys.html">密钥管理</a>列表中即可被引用（支持 <code>~/</code> 前缀、绝对路径与 <code>~/.ssh/</code> 相对路径解析）</li><li>「导出」即对 <code>~/.ssh/config</code> 的读写能力（结构化重写 / 原文覆写）；当前没有「把 vShell 连接导出回 config」的功能</li></ul><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./connections.html">连接与分组管理</a></li><li><a href="./keys.html">SSH 密钥管理</a></li></ul>`,26)])])}const u=e(s,[["render",n]]);export{g as __pageData,u as default};
